{
  "root": "main_stack",
  "state": {
    "steps": [
      {
        "stepNumber": 1,
        "title": "Arrival and Immigration",
        "description": "After disembarking your flight at NRT (Terminal 1 or 2/3), follow signs for \"Arrivals,\" \"Immigration,\" and \"Baggage Claim.\" Once you have cleared customs and collected your luggage, proceed to the main arrival lobby.",
        "icon": "../assets/r_000241_01_14_airplane.svg"
      },
      {
        "stepNumber": 2,
        "title": "Finding the JR Narita Express (N'EX)",
        "description": "In the arrival lobby, look for signs directing you to \"Trains\" or \"JR Line\" (Japan Railways). The JR Narita Express ticketing counters and platforms are located in the basement levels of both Terminal 1 and Terminal 2/3. Follow the red \"JR\" logo signs.",
        "icon": "../assets/r_000241_01_8_signpost-split.svg"
      },
      {
        "stepNumber": 3,
        "title": "Purchasing Tickets",
        "description": "You can purchase tickets from the staffed JR Ticket Office (Midori-no-Madoguchi), often indicated by a green sign. Staff can assist you in English. Automated Ticket Vending Machines are also available, with English language options. Important: Ensure you purchase a ticket specifically for the Narita Express (N'EX) to Shinjuku. Seats are reserved. A one-way ticket from NRT to Shinjuku costs approximately ¥3,200 - ¥3,500 for an ordinary car.",
        "icon": "../assets/r_000249_01_3_ticket-perforated.svg"
      },
      {
        "stepNumber": 4,
        "title": "Boarding the N'EX",
        "description": "Once you have your ticket, proceed through the JR ticket gates. Check your ticket for the correct platform number and train departure time. The N'EX trains are clearly marked. Locate your assigned car and seat number. There is ample space for luggage storage within the train carriages.",
        "icon": "../assets/r_000249_01_4_train-front-fill.svg"
      },
      {
        "stepNumber": 5,
        "title": "Travel to Shinjuku",
        "description": "The Narita Express provides a comfortable journey with dedicated luggage racks, overhead storage, and restrooms. The train makes several stops before reaching Shinjuku, but you do not need to change trains. The approximate travel time from Narita Airport to Shinjuku Station is 80 to 90 minutes.",
        "icon": "../assets/r_000249_01_5_clock.svg"
      },
      {
        "stepNumber": 6,
        "title": "Arriving at Shinjuku Station",
        "description": "Shinjuku Station is one of Tokyo's largest and busiest stations. Upon arrival, follow signs for \"Exits\" (East, West, South, New South) depending on your final destination within Shinjuku. Use the detailed station maps available or consult station staff if you need assistance navigating to your specific hotel or attraction.",
        "icon": "../assets/r_000241_01_2_building.svg"
      }
    ],
    "key_details": [
      {
        "detail": "Approximate Travel Time",
        "value": "80-90 minutes"
      },
      {
        "detail": "Approximate One-Way Cost",
        "value": "¥3,200 - ¥3,500 (Ordinary Car)"
      },
      {
        "detail": "Service Frequency",
        "value": "Typically 1-2 trains per hour"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "intro_text",
        "step_by_step_heading",
        "steps_table",
        "key_details_heading",
        "key_details_table",
        "quick_actions_heading",
        "quick_actions_stack",
        "sources_heading",
        "sources_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Tokyo Narita to Shinjuku: Narita Express Guide",
        "variant": "h2"
      },
      "children": []
    },
    "intro_text": {
      "type": "Text",
      "props": {
        "text": "The Narita Express (N'EX) offers a direct, comfortable, and efficient way to travel from Tokyo Narita International Airport (NRT) to Shinjuku Station. This guide outlines the steps, approximate travel time, and cost for your journey."
      },
      "children": []
    },
    "step_by_step_heading": {
      "type": "Text",
      "props": {
        "text": "Step-by-Step Narita Express Journey",
        "variant": "h3"
      },
      "children": []
    },
    "steps_table": {
      "type": "Table",
      "props": {
        "statePath": "/steps",
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "title",
        "columns": [
          {
            "key": "icon",
            "label": "Icon"
          },
          {
            "key": "title",
            "label": "Step"
          },
          {
            "key": "description",
            "label": "Details"
          }
        ]
      },
      "children": []
    },
    "key_details_heading": {
      "type": "Text",
      "props": {
        "text": "Key Travel Details",
        "variant": "h3"
      },
      "children": []
    },
    "key_details_table": {
      "type": "Table",
      "props": {
        "statePath": "/key_details",
        "domain": "generic",
        "preferredPresentation": "table",
        "columns": [
          {
            "key": "detail",
            "label": "Detail"
          },
          {
            "key": "value",
            "label": "Value"
          }
        ]
      },
      "children": []
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "nex_info_button",
        "nrt_access_button"
      ]
    },
    "nex_info_button": {
      "type": "Button",
      "props": {
        "label": "Narita Express Information"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.jreast.co.jp/multi/en/nex/"
          }
        }
      },
      "children": []
    },
    "nrt_access_button": {
      "type": "Button",
      "props": {
        "label": "Narita Airport Access Guide"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.narita-airport.jp/en/access/train/"
          }
        }
      },
      "children": []
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "jr_east_button",
        "nrt_airport_button"
      ]
    },
    "jr_east_button": {
      "type": "Button",
      "props": {
        "label": "JR East Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.jreast.co.jp/"
          }
        }
      },
      "children": []
    },
    "nrt_airport_button": {
      "type": "Button",
      "props": {
        "label": "Narita International Airport Official Website"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.narita-airport.jp/"
          }
        }
      },
      "children": []
    }
  }
}
